namespace RecipeHub.Data;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals and sandwiches", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
            new() { Name = "Appetizers", Description = "Starters and small bites", Icon = "🧆" },
            new() { Name = "Drinks", Description = "Smoothies, cocktails, and more", Icon = "🍹" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nButter for cooking",
                Steps = "1. Mix dry ingredients\n2. Whisk eggs and milk together\n3. Combine wet and dry ingredients\n4. Cook on buttered griddle until golden",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "Romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop romaine\n2. Toss with dressing\n3. Add croutons and parmesan\n4. Top with grilled chicken",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion\n2 cloves garlic\n400ml tomato sauce\nOlive oil\nSalt and pepper",
                Steps = "1. Cook spaghetti according to package\n2. Sauté onion and garlic in olive oil\n3. Brown the ground beef\n4. Add tomato sauce, simmer 20 minutes\n5. Serve sauce over pasta",
                AverageRating = 4.8, RatingCount = 20
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n100g butter\n2 eggs\n2 egg yolks\n50g sugar\n30g flour",
                Steps = "1. Melt chocolate and butter together\n2. Whisk eggs, yolks, and sugar\n3. Fold in chocolate mixture and flour\n4. Pour into greased ramekins\n5. Bake at 220°C for 12 minutes",
                AverageRating = 4.9, RatingCount = 15
            },
            new()
            {
                Id = 5, Title = "Bruschetta", Category = "Appetizers",
                Ingredients = "Baguette slices\nTomatoes\nFresh basil\nGarlic\nOlive oil\nBalsamic vinegar",
                Steps = "1. Toast baguette slices\n2. Dice tomatoes and mix with basil, garlic, olive oil\n3. Spoon mixture onto toast\n4. Drizzle with balsamic vinegar",
                AverageRating = 4.3, RatingCount = 6
            },
            new()
            {
                Id = 6, Title = "Berry Smoothie", Category = "Drinks",
                Ingredients = "1 cup mixed berries\n1 banana\n1 cup yogurt\n½ cup milk\n1 tbsp honey",
                Steps = "1. Add all ingredients to blender\n2. Blend until smooth\n3. Pour into glass and serve immediately",
                AverageRating = 4.6, RatingCount = 10
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int stars)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }
}

@page "/recipes/{CategoryName}"
@inject RecipeHub.Data.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<RecipeHub.Data.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeHub.Data.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: <a href="/recipes/@recipe.Category">@recipe.Category</a></p>

    <div class="row">
        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>

            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Steps</h5></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Rating</h5></div>
                <div class="card-body">
                    <p>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
                    <StarRating RecipeId="@recipe.Id" />
                </div>
            </div>
        </div>
    </div>

    <a href="/recipes/@recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }
    private RecipeHub.Data.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Data.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@Model.Title</strong>" with the community.</p>
        <a href="/recipes/@Model.Category" class="btn btn-primary">View in @Model.Category</a>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="Model.Title" class="form-control" />
            <ValidationMessage For="() => Model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="Model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in categories)
                {
                    <option value="@cat.Name">@cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Model.Ingredients" class="form-control" rows="6" />
            <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Model.Steps" class="form-control" rows="6" />
            <ValidationMessage For="() => Model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel Model { get; set; } = new();
    private List<RecipeHub.Data.RecipeCategory> categories = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        var recipe = new RecipeHub.Data.Recipe
        {
            Title = Model.Title,
            Category = Model.Category,
            Ingredients = Model.Ingredients,
            Steps = Model.Steps
        };
        RecipeService.AddRecipe(recipe);
        submitted = true;
    }

    private sealed class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be under 100 characters")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Data.RecipeService RecipeService

<div class="star-rating">
    @if (hasRated)
    {
        <p class="text-success mb-0">Thanks! You rated this @userRating ★</p>
    }
    else
    {
        <p class="mb-1">Rate this recipe:</p>
        <div>
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button class="btn btn-link p-0 fs-4 text-decoration-none @(star <= hoverStar ? "text-warning" : "text-muted")"
                        @onclick="() => Rate(star)"
                        @onmouseover="() => hoverStar = star"
                        @onmouseout="() => hoverStar = 0"
                        aria-label="Rate @star stars">
                    ★
                </button>
            }
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int hoverStar;
    private int userRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        RecipeService.RateRecipe(RecipeId, stars);
        userRating = stars;
        hasRated = true;
    }
}

